// Byte-for-byte agreement with the Rust implementation (testdata/sdk-vectors.json,
// generated by crates/tsn-core/tests/sdk_vectors.rs).

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { ed25519 } from "@noble/curves/ed25519.js";
import { bytesToHex, hexToBytes } from "../src/bytes.js";
import { decodeAddress, encodeAddress } from "../src/bech32.js";
import { childXOnly, keyAddress, ownerPath, tweak } from "../src/derive.js";
import { requestDigest } from "../src/digest.js";
import { authorize, ownerFromSecret } from "../src/owner.js";
import type { Tx } from "../src/types.js";

const v = JSON.parse(readFileSync(new URL("../../../testdata/sdk-vectors.json", import.meta.url), "utf8"));

describe("addresses", () => {
  for (const a of v.addresses) {
    it(`${a.prefix} v${a.version}`, () => {
      expect(encodeAddress(a.prefix, a.version, hexToBytes(a.data))).toBe(a.address);
      const d = decodeAddress(a.address);
      expect([d.prefix, d.version, bytesToHex(d.data)]).toEqual([a.prefix, a.version, a.data]);
    });
  }
  it("rejects a bad checksum", () => {
    const a = v.addresses[0].address as string;
    const bad = a.slice(0, -1) + (a.endsWith("q") ? "p" : "q");
    expect(() => decodeAddress(bad)).toThrow(/checksum/);
  });
});

describe("derivation", () => {
  for (const d of v.derivations) {
    it(`${d.name} under ${d.master_public_key.slice(0, 10)}…`, () => {
      expect(ownerPath(d.owner_public_key, d.name)).toBe(d.path);
      expect(tweak(hexToBytes(d.master_public_key), d.path).toString(16).padStart(64, "0")).toBe(d.tweak);
      expect(bytesToHex(childXOnly(d.master_public_key, d.path))).toBe(d.xonly);
      expect(keyAddress(d.master_public_key, d.owner_public_key, d.name, "kaspa-testnet").address).toBe(d.kaspa_testnet_address);
      expect(keyAddress(d.master_public_key, d.owner_public_key, d.name, "hoosat-mainnet").address).toBe(d.hoosat_mainnet_address);
    });
  }
});

describe("authorization digest", () => {
  const a = v.authorization;
  const tx = a.tx as Tx;

  it("matches Rust, including amounts above 2^53", () => {
    expect(bytesToHex(requestDigest(a.key_id, a.path, a.request_id, a.expires_at, tx))).toBe(a.digest);
  });

  it("owner key and signature match Rust", () => {
    const owner = ownerFromSecret(a.owner_secret);
    expect(owner.public).toBe(a.owner_public_key);
    expect(bytesToHex(ed25519.sign(hexToBytes(a.digest), hexToBytes(owner.secret)))).toBe(a.owner_sig);
  });

  it("ignores signature scripts but nothing else", () => {
    const base = bytesToHex(requestDigest(a.key_id, a.path, a.request_id, a.expires_at, tx));
    const signed: Tx = { ...tx, inputs: tx.inputs.map((i) => ({ ...i, signature_script: "41" + "00".repeat(65) })) };
    expect(bytesToHex(requestDigest(a.key_id, a.path, a.request_id, a.expires_at, signed))).toBe(base);
    const changed: Tx = { ...tx, outputs: tx.outputs.map((o, i) => (i === 0 ? { ...o, amount: "100000001" } : o)) };
    expect(bytesToHex(requestDigest(a.key_id, a.path, a.request_id, a.expires_at, changed))).not.toBe(base);
  });

  it("authorize produces a verifiable signature", () => {
    const owner = ownerFromSecret(a.owner_secret);
    const auth = authorize(owner, a.key_id, a.path, tx, 600, 1_700_000_000_000);
    expect(auth.expires_at).toBe(1_700_000_600);
    const digest = requestDigest(a.key_id, a.path, auth.request_id, auth.expires_at, tx);
    expect(ed25519.verify(hexToBytes(auth.owner_sig), digest, hexToBytes(owner.public))).toBe(true);
  });
});
